window.RP_SESSION={"id":"S-57619df3881f","messages":[{"id":"RP-0253576","time":"2026-08-29T00:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"절그럭- 절그럭-","characters":["P-6a1a99e98a44"]},{"id":"RP-0253577","time":"2026-08-29T00:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"야심한 밤, 훈련장에서 쇠사슬이 흔들리는 소리가 들려옵니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253578","time":"2026-08-29T00:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"가델랏 허그는 적당한 크기의 바위 하나를 양 손으로 힘겹게 들고, 뒤뚱뒤뚱… 이내 훈련장에 도착합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253579","time":"2026-08-29T00:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄으으으— 끄하!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253580","time":"2026-08-29T00:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"쿵-","characters":["P-6a1a99e98a44"]},{"id":"RP-0253581","time":"2026-08-29T00:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"바위를 던지듯 바닥에 내려두고, 허그는 잠시 숨을 고릅니다.\n잠깐의 시간이 지난 후, 허그는 바위를 기울여 잘 세워둔 뒤 장작 몇개를 주위에 둘러 바위를 고정시켜둡니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253582","time":"2026-08-29T00:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어휴, 음! 잘 됬네.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253583","time":"2026-08-29T00:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 오늘도 힘내보자고~ 실력이 녹슬면 돈 값을 못하게 되버리니깐 말이야.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253584","time":"2026-08-29T00:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"절그럭- 절그럭- 허그는 뒤로 물러납니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253585","time":"2026-08-29T00:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"차르르르…\n\n허리춤에서 철퇴를 집어든 뒤 사슬을 늘어뜨리고, 다시 손으로 적당히 감아 사슬의 길이를 맞춥니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253586","time":"2026-08-29T00:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아마 이쯤이면 될 듯 하니,","characters":["P-6a1a99e98a44"]},{"id":"RP-0253587","time":"2026-08-29T00:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"철퇴를 몸 뒤로 던져 넘긴 후, 크게 받침발을 굴러 박고.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253588","time":"2026-08-29T00:52:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"힘을 실어 철퇴를 휘두르며 띄우면서—\n회전을 강하게 실어!","characters":["P-6a1a99e98a44"]},{"id":"RP-0253589","time":"2026-08-29T00:52:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-6a1a99e98a44"]},{"id":"RP-0253590","time":"2026-08-29T00:52:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 힘 판정 :\n[2] + [2] = [4]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0253591","time":"2026-08-29T00:52:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"훙~","characters":["P-6a1a99e98a44"]},{"id":"RP-0253592","time":"2026-08-29T00:53:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 자신있게 철퇴를 날려보냈으나, 줄을 조금 짧게 풀어낸 탓인지, 철퇴는 바위에 닿지 않고 근처를 스쳐지나갑니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253593","time":"2026-08-29T00:54:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄아~ 역시 골치아프단 말이야 이건, 아무리 오랫동안 휘둘러봐도 멀리선 결국엔 감으로 맞춰야하니까…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253594","time":"2026-08-29T00:54:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 큰 궤적을 그리며 날아가는 철퇴를 바닥에 파바바박- 끄시며 속도를 줄이고, 다시 이쪽으로 끌어당깁니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253595","time":"2026-08-29T00:55:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"실패해도 다시, 방금은 아쉬웠지만 이번엔 어느정도 감이 잡힌 듯 합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253596","time":"2026-08-29T00:56:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 손을 꼼지락 거리며 말린 사슬을 조금 더 풀고, 이번에도 철퇴를 뒤로 넘긴 후에,","characters":["P-6a1a99e98a44"]},{"id":"RP-0253597","time":"2026-08-29T00:56:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이번에는 분명 맞을 것이라는 생각으로, 회전을 한 번 더 실어냅니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253598","time":"2026-08-29T00:56:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"부웅부웅~","characters":["P-6a1a99e98a44"]},{"id":"RP-0253599","time":"2026-08-29T00:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"다시 바위를 향해 철퇴를 크게 가로로 휘둘러 보입니다!","characters":["P-6a1a99e98a44"]},{"id":"RP-0253600","time":"2026-08-29T00:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“흐읍—”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253601","time":"2026-08-29T00:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-6a1a99e98a44"]},{"id":"RP-0253602","time":"2026-08-29T00:57:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 힘 판정 :\n[4] + [2] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0253603","time":"2026-08-29T00:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"훙~~","characters":["P-6a1a99e98a44"]},{"id":"RP-0253604","time":"2026-08-29T00:57:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"움찔.","characters":["P-337878fc286e"]},{"id":"RP-0253605","time":"2026-08-29T00:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이런, 이번에도 짧습니다!","characters":["P-6a1a99e98a44"]},{"id":"RP-0253606","time":"2026-08-29T00:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄아~~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253607","time":"2026-08-29T00:58:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"들려오는 둔탁한 굉음을 향해 발걸음을 옮겨봅니다. 누가 이 밤중에...?","characters":["P-337878fc286e"]},{"id":"RP-0253609","time":"2026-08-29T00:58:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"하고 찾아가보니, 아. 또 훈련장이구나.\n\n여긴 이렇게 막 써도 되는 곳인가~ 하고 쳐다봅니다.","characters":["P-337878fc286e"]},{"id":"RP-0253610","time":"2026-08-29T00:59:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 이번엔 멈추지 않고 돌아가는 몸을 그대로 쭉 움직이다가~","characters":["P-6a1a99e98a44"]},{"id":"RP-0253611","time":"2026-08-29T00:59:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"저번엔 메이스로 허수아비를 박살내더니, 이번엔 돌이네요. 저것도 내가 치워야할텐데...","characters":["P-337878fc286e"]},{"id":"RP-0253613","time":"2026-08-29T00:59:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아무튼!","characters":["P-6a1a99e98a44"]},{"id":"RP-0253614","time":"2026-08-29T01:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오른팔을 위로 치켜올려, 철퇴가 위를 향해 궤도를 그리도록 만든 뒤!","characters":["P-6a1a99e98a44"]},{"id":"RP-0253615","time":"2026-08-29T01:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"대각선으로, 내려찍자!!","characters":["P-6a1a99e98a44"]},{"id":"RP-0253616","time":"2026-08-29T01:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“으랴—!!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253617","time":"2026-08-29T01:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-6a1a99e98a44"]},{"id":"RP-0253618","time":"2026-08-29T01:00:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 힘 판정 :\n[11] + [2] = [13]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0253619","time":"2026-08-29T01:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"콰앙!!","characters":["P-6a1a99e98a44"]},{"id":"RP-0253620","time":"2026-08-29T01:01:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그의 철퇴가 매서운 속도로 바위에 부딪히자, 바위의 위쪽이 조금 떨어져 나가며, 파입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253621","time":"2026-08-29T01:01:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“휴~ 여이, 역시 아직 안죽었는걸~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253622","time":"2026-08-29T01:02:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그리고 그제서야 입을 여네요. \n\n\" 이게... 다 뭡니까? \"","characters":["P-337878fc286e"]},{"id":"RP-0253623","time":"2026-08-29T01:02:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“헉.”\n\n허그 당황","characters":["P-6a1a99e98a44"]},{"id":"RP-0253624","time":"2026-08-29T01:02:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 보는 식구가 있었구만~ 보다시피 훈련 중이었다고.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253625","time":"2026-08-29T01:02:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 보는 것보다, 들었다고 하는 편이 맞겠군요. \"","characters":["P-337878fc286e"]},{"id":"RP-0253626","time":"2026-08-29T01:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”듣는 식구였네~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253627","time":"2026-08-29T01:03:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 막 잠에 들려던 참이었는데 말이죠, 뭔가 큰 소리가 나서. \"","characters":["P-337878fc286e"]},{"id":"RP-0253628","time":"2026-08-29T01:04:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 제가 신입인 입장이라 함부로 말하기 조금 그렇지만, 혹시 조금 소리를 줄여주실 수 있겠습니까? \"","characters":["P-337878fc286e"]},{"id":"RP-0253629","time":"2026-08-29T01:04:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 아니면 밖에서 마저 훈련을 이어서 하는 것도 좋겠네요. \"","characters":["P-337878fc286e"]},{"id":"RP-0253630","time":"2026-08-29T01:04:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“헉, 그정도로 컸으려나? 미안한걸, 항상 허수아비로 훈련하다가 이번에 뭔가 단단한걸 써보고 싶었어서 말이지.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253631","time":"2026-08-29T01:05:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아무래도 그 편이 좋겠는걸, 미안하네.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253632","time":"2026-08-29T01:05:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ... \"","characters":["P-337878fc286e"]},{"id":"RP-0253633","time":"2026-08-29T01:05:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 저 허수아비는 누가 고쳐놓는 건지 아십니까? \"","characters":["P-337878fc286e"]},{"id":"RP-0253634","time":"2026-08-29T01:06:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“음… 아무래도 길드의 다른 식구들이…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253635","time":"2026-08-29T01:06:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 볼 때마다 매번 부서져있고, 또 고쳐져있더군요... \"","characters":["P-337878fc286e"]},{"id":"RP-0253636","time":"2026-08-29T01:06:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 아마 담당자가 고생이 많을 것 같습니다. \"","characters":["P-337878fc286e"]},{"id":"RP-0253637","time":"2026-08-29T01:07:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하. 여이, 그러게 말이야.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253638","time":"2026-08-29T01:07:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...아무튼, 그렇습니까. 배려해주시면 감사하겠습니다. \"","characters":["P-337878fc286e"]},{"id":"RP-0253639","time":"2026-08-29T01:07:00+09:00","room":"RP","name":"샤온 오구라","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"하고 꾸벅, 허리 숙여 인사하곤, 훈련장을 떠납니다.","characters":["P-337878fc286e"]},{"id":"RP-0253640","time":"2026-08-29T01:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그래, 여이~! 조심할테니까 말이야, 잘 들어가라고~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253641","time":"2026-08-29T01:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 주섬주섬 철퇴를 주워들면서 크게 손을 흔듭니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253642","time":"2026-08-29T01:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아무래도 다음부턴 나무토막이 낫겠는걸, 여이!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253643","time":"2026-08-29T01:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그럼 이만 나도 정리하고…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253644","time":"2026-08-29T01:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 말하며 허그는 철퇴를 허리춤에 다시 걸고, 깨진 바위를 향해…","characters":["P-6a1a99e98a44"]},{"id":"RP-0253645","time":"2026-08-29T01:10:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…엥?","characters":["P-6a1a99e98a44"]},{"id":"RP-0253646","time":"2026-08-29T01:10:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"바위의 주변엔 분명 떨어져 나간 바위의 파편들이 너저분하게 뒹굴고 있습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253647","time":"2026-08-29T01:10:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…바위의?","characters":["P-6a1a99e98a44"]},{"id":"RP-0253648","time":"2026-08-29T01:11:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이상하다, 분명 바위에서 떨어져 나온 것들일 텐데, 어째서 유독 반짝거리고 검은 것이…","characters":["P-6a1a99e98a44"]},{"id":"RP-0253649","time":"2026-08-29T01:11:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…엥??“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253650","time":"2026-08-29T01:11:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 문득 생각이 들어 자신의 철퇴를 황급히 내려다 봅니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253651","time":"2026-08-29T01:12:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이런, 철퇴의 가시가 있던 자리 둘이 민둥민둥하게 만들어져있네요!","characters":["P-6a1a99e98a44"]},{"id":"RP-0253652","time":"2026-08-29T01:12:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇다면…","characters":["P-6a1a99e98a44"]},{"id":"RP-0253653","time":"2026-08-29T01:12:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"역시나, 바닥에서 나뒹굴고 있는 바위 파편 사이로 떨어져 나간 가시 두 개가 눈에 들어옵니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253654","time":"2026-08-29T01:13:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아무래도 무리하게 힘을 실어 불안정한 자세로 돌을 때려버린 탓 같네요. 그러게 누가 2쓰라린 하래~","characters":["P-6a1a99e98a44"]},{"id":"RP-0253655","time":"2026-08-29T01:13:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"사람 때리는 무기로 바위를 그리 세게 치면 쓰나.\"\n\n인기척도 없이, 돌연 옆에 나타난 누군가.","characters":["P-22fdf8486544"]},{"id":"RP-0253656","time":"2026-08-29T01:14:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…헉!!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253657","time":"2026-08-29T01:15:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 깜짝이야! 그렇게 갑자기 나타나버리면 놀란다고.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253658","time":"2026-08-29T01:15:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아무래도 뭔가 오늘따라 단단한 녀석에게 세게 부딪혀보고 싶은 기분이 들었어서 말이지.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253659","time":"2026-08-29T01:16:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"그런 기분이 든다고 무작정 부딪히면 끝이 좋지 않을 거야.\"","characters":["P-22fdf8486544"]},{"id":"RP-0253660","time":"2026-08-29T01:17:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하, 이번이 한두번도 아니고 말이지. 가끔씩 하고싶은 대로 곧장 하게 되버리네.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253661","time":"2026-08-29T01:18:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이~ 그쪽은 누구야? 처음 보는 것 같은데, 이 밤에 무슨 일로 돌아다닌담?“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253662","time":"2026-08-29T01:19:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"나? 나도 길드원이야. 그나저나 아까 철퇴 던지는 거 봤는데, 잘 안되나봐?\"","characters":["P-22fdf8486544"]},{"id":"RP-0253663","time":"2026-08-29T01:20:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”하하하, 이런! 부끄러운 광경을 보여버렸는걸~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253664","time":"2026-08-29T01:20:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아무리 오랫동안 길들여왔어도 멀리서 휘두르는건 도통 한번에 팍! 되는 때가 적어서 말이야. 그래도 만약을 대비해서 잘 연습해둬야지!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0253665","time":"2026-08-29T01:21:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"무기 투척은 말야, 무기를 잃는 것이니 신중하게 써야 해. 팁 하나 줄까?\"\n\n\"마음으로 던져.\"","characters":["P-22fdf8486544"]},{"id":"RP-0253666","time":"2026-08-29T01:22:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“엥? 마음? 잘 보고 던진다거나 그런게 아니라?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253667","time":"2026-08-29T01:23:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"그녀가 쳐다봤을 때, 그는 없었다. 마치 처음부터 아무도 없었던 것처럼.","characters":["P-22fdf8486544"]},{"id":"RP-0253668","time":"2026-08-29T01:23:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“???”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253669","time":"2026-08-29T01:23:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 요술인가?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253670","time":"2026-08-29T01:24:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여~어이! 하던 말은 마저 하고 가야지!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253671","time":"2026-08-29T01:24:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어엥, 내가 졸려서 헛것이라도 보이는 건가?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253672","time":"2026-08-29T01:24:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그 노란색 개구리도 그렇고 말이야.\n끄아~ 아무래도 너무 늦은 밤에 돌아다니는건 안좋을 것 같은걸.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253673","time":"2026-08-29T01:25:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“오늘은 이만 돌아가자고. 언제 가시도 다시 박고…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253674","time":"2026-08-29T01:25:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 바위와 파편들을 들어 다시 뒤뚱거리며 훈련장을 벗어난 뒤, 저 멀리 숲에 도로 던져 돌려둡니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253675","time":"2026-08-29T01:25:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 길드 본관으로 돌아가는 길에…","characters":["P-6a1a99e98a44"]},{"id":"RP-0253676","time":"2026-08-29T01:25:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"슬쩍.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253677","time":"2026-08-29T01:26:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"훈련장 쪽을 돌아보고는.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253678","time":"2026-08-29T01:26:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이~ 말 고마워! 잘 들어가라고~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0253679","time":"2026-08-29T01:26:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러곤 다시 제 갈 길을 걸어갑니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0253680","time":"2026-08-29T01:29:00+09:00","room":"RP","name":"피에르","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"어유, 밤이 어째 쌀쌀허네..\"\n\n피에르는 제 갈길을 가는 허그를 바라보며, 뒤늦게 훈련장에 들어섰다.\n\n늘 야밤이 되면 훈련을 하는 버릇이 있던 피에르는 오늘도 늘 써오던 목검을 들며, 허수아비를 향해 공격을 해 갔다.","characters":["P-1ba0b80ec424"]},{"id":"RP-0253681","time":"2026-08-29T01:30:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"여어.\"\n\n훈련장 울타리에 기대어 말을 걸어오는 그. 피에르라면 어렵지 않게 누구인지 알아봤을 것이다.","characters":["P-22fdf8486544"]},{"id":"RP-0253682","time":"2026-08-29T01:31:00+09:00","room":"RP","name":"피에르","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"...? 티아멧 나으리 어니셔유?\"\n\n피에르는 자신이 잘못 들은 것인지, 한번 더 확인을 한 뒤, 이내 티아멧이 맞다는 사실을 알 수 있었다.\n\n\"여자가 되신줄 알었는디 그려도 다시 돌아오셨네유? 디따 오래간만이구먼유.\"","characters":["P-1ba0b80ec424"]},{"id":"RP-0253683","time":"2026-08-29T01:34:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"뭐, 그리 됐다.\"\n\n어께를 으쓱하고는 울타리에 기대었던 몸을 일으켜 그에게 다가간다.\n\n\"야밤에... 같이 구울 잡으러 공동묘지 갔던 거 기억나냐?\"","characters":["P-22fdf8486544"]},{"id":"RP-0253684","time":"2026-08-29T01:34:00+09:00","room":"RP","name":"피에르","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"어유, 기억나지유. 그때 거... 거스트인지 뭔지 허는 거슥헌티 갈 뻔혔었던 적도 기억이 나는구먼유.\"\n\n피에르는 그때를 상상하며 몸을 부르르 떨었다.","characters":["P-1ba0b80ec424"]},{"id":"RP-0253685","time":"2026-08-29T01:36:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"하하하, 너라면 기억해줄 줄 알았어 임마.\"\n\n살갑게 웃으며 좋아하는 것이, 영락없는 그였다. 반가운 용병.\n\n훈련장 한구석에 앉는다.","characters":["P-22fdf8486544"]},{"id":"RP-0253686","time":"2026-08-29T01:37:00+09:00","room":"RP","name":"피에르","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"어유, 당연허지유. 나으리가 주신 대추 나무도 기억허고 있는디. 그려서 요즘은 뭘 허구 지내셨대유? 어째 얼굴 한번 뵈는게 힘드구먼유.\"\n\n피에르도 티아멧을 따라 티아멧 주변에 있는 나무상자중 하나에 앉았다.","characters":["P-1ba0b80ec424"]},{"id":"RP-0253687","time":"2026-08-29T01:43:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"그러게나 말이다, 요새 정신이 없어서 말이지. 세상은 이렇게 아름다운데.\"\n\n울타리에 기대어 밤하늘을 바라보는 그의 투구에 별빛이 내린다.\n\n쏟아질 듯 수놓아진 별빛과 늦여름의 풀벌레 소리, 그리고 그. 조금 뒤, 먼저 입을 연다.\n\n\"반가웠다. 잘 지내고.\"","characters":["P-22fdf8486544"]},{"id":"RP-0253688","time":"2026-08-29T01:44:00+09:00","room":"RP","name":"피에르","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그릏긴 허지유.\"\n\n피에르는 티아멧의 말에 공감하며, 티아멧을 따라 밤하늘을 들여다 봤다.\n\n...피에르는 늘상 봐오던 별빛이 아름답다, 예쁘다는 생각이 들진 않았지만 오랜만에 느껴보는 이 분위기에 만족감을 느낄 수 있었다.\n\n\"? 어유, 당연히 지는 잘 지내지유. 어디 가시려는 거여유?\"","characters":["P-1ba0b80ec424"]},{"id":"RP-0253689","time":"2026-08-29T01:46:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"그가 옆을 돌아봤을 때, 아까 사라진 것처럼 그는 없었다. 늦은 밤의 바람만이 휘날려 그의 빈자리를 훑고 간다.","characters":["P-22fdf8486544"]},{"id":"RP-0253690","time":"2026-08-29T01:47:00+09:00","room":"RP","name":"피에르","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"...?\"\n\n피에르는 주변을 두리번 거리며 티아멧을 찾았다.\n\n하지만 피에르는 역시 티아멧을 찾지 못했고, 머리를 긁적일 뿐이었다.\n\n\"우음... 무슨 일이람...?\"\n\n피에르는 이내 이 세상을 이해하기를 포기하고, 다시 목검을 들어 검술 훈련이나 하기 시작했다...","characters":["P-1ba0b80ec424"]},{"id":"RP-0253691","time":"2026-08-29T01:53:00+09:00","room":"RP","name":"피에르","profile":"피에르","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-1ba0b80ec424"]},{"id":"RP-0253692","time":"2026-08-29T01:53:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
